from pathlib import Path
import markdown,yaml,re,json,html,shutil,hashlib
root=Path('/Users/ani/Projects/fyipen-projects/supaboard/supaboard-content/drafts/financial-dashboard-examples/revision-2')
source=root/'financial-dashboard-examples.md'
_,meta,body=source.read_text().split('---',2)
fm=yaml.safe_load(meta)
article=markdown.markdown(body.strip(),extensions=['extra','toc','sane_lists'])
for name in ['performance','aging','invoices','review']:
 article=article.replace('<!-- FIGURE: '+name+' -->',(root/'figures'/(name+'.html')).read_text())
article=re.sub(r'<table>', '<div class="table-scroll" role="region" aria-label="Financial dashboard comparison" tabindex="0"><table>', article).replace('</table>','</table></div>')
article=article.replace('aria-label="Financial dashboard comparison"', 'aria-label="Financial KPI review worksheet"')
article=re.sub(r'<th(?=[ >])', '<th scope="col"', article)
shutil.copyfile(root.parent/'hero.webp',root/'hero.webp')
words=len(re.sub('<[^>]+>',' ',article).split())
css='''
:root{color-scheme:light dark;--bg:#f7f6f2;--paper:#fff;--ink:#182523;--muted:#596560;--line:#dce4de;--accent:#14634b;--wash:#f0f5f1}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font-family:Georgia,'Times New Roman',serif;font-size:18px;line-height:1.75}.page{max-width:920px;margin:48px auto 80px;background:var(--paper);padding:58px 76px 54px;border:1px solid var(--line);border-radius:4px}.review{font:11px/1.5 system-ui,sans-serif;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);display:flex;gap:20px;justify-content:space-between;margin-bottom:28px}h1,h2,nav,table,footer{font-family:system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}h1{font-size:clamp(32px,4.5vw,47px);line-height:1.13;letter-spacing:-1.6px;margin:0 0 24px;font-weight:760}nav{font-size:12px;line-height:1.6;border-bottom:1px solid var(--line);padding-bottom:26px;margin-bottom:32px;display:flex;gap:16px;flex-wrap:wrap}nav a{text-decoration:none}a{color:var(--accent);text-underline-offset:3px;text-decoration-thickness:1px}a:hover{text-decoration-thickness:2px}a:focus-visible,[tabindex]:focus-visible{outline:2px solid var(--accent);outline-offset:4px}p{margin:0 0 20px}h2{font-size:26px;line-height:1.28;letter-spacing:-.65px;margin:42px 0 18px;scroll-margin-top:24px}strong{font-weight:700}article>p:first-child{font-size:20px;line-height:1.6}table{width:100%;border-collapse:collapse;font-size:12.5px;line-height:1.6;margin:0;min-width:570px}th{background:var(--wash);font-size:11px;text-align:left;letter-spacing:.01em}th,td{border:1px solid var(--line);padding:12px 11px;vertical-align:top}tbody tr:nth-child(even){background:var(--wash)}.table-scroll{overflow-x:auto;margin:25px 0 12px}p:has(>em:only-child){font-size:13px;line-height:1.6;color:var(--muted);font-family:system-ui,sans-serif;margin-bottom:24px}footer{border-top:1px solid var(--line);padding-top:20px;margin-top:36px;color:var(--muted);font-size:12px;line-height:1.6}footer p{margin:0}::selection{background:#cee5d7} @media(max-width:700px){.page{margin:0;padding:32px 22px 40px;border:0;border-radius:0}body{font-size:17px}h1{letter-spacing:-1px}h2{font-size:24px}article>p:first-child{font-size:19px}.review{gap:12px;font-size:10px}nav{gap:8px 16px}.table-scroll{margin-right:-3px}}
@media(prefers-color-scheme:dark){:root{--bg:#111a17;--paper:#18231f;--ink:#e8eee9;--muted:#a7b7ad;--line:#34453a;--accent:#8ed5b6;--wash:#203127}}
'''
css+=(root/'figure-styles.css').read_text()
schema={'@context':'https://schema.org','@type':'BlogPosting','headline':fm['title'],'description':fm['description'],'inLanguage':'en','wordCount':words,'keywords':['financial dashboard examples','accounts receivable dashboard','financial KPI dashboard','accounts receivable aging report'],'citation':['https://www.sec.gov/about/reports-publications/beginners-guide-financial-statements','https://www.accaglobal.com/sg/en/student/exam-support-resources/fundamentals-exams-study-resources/f9/technical-articles/arm.html']}
head=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{html.escape(fm['title'])}</title><meta name="description" content="{html.escape(fm['description'],quote=True)}"><meta property="og:type" content="article"><meta property="og:title" content="{html.escape(fm['title'],quote=True)}"><meta property="og:description" content="{html.escape(fm['description'],quote=True)}"><meta property="og:image" content="hero.webp"><meta property="og:image:alt" content="Green financial indicators above unpaid invoices and a clock, an editorial illustration."><meta name="twitter:card" content="summary_large_image"><meta name="article-source-sha256" content="{hashlib.sha256(source.read_bytes()).hexdigest()}"><style>{css}</style><script type="application/ld+json">{json.dumps(schema)}</script></head>'''
page=f'''{head}<body><main class="page"><div class="review"><span>Finance &amp; operations</span><span>Review copy · {words:,} words</span></div><article><h1>{html.escape(fm['title'])}</h1><nav aria-label="Article sections"><a href="#1-profitability-dashboard-is-sales-growth-more-profitable">Profitability</a><a href="#2-accounts-receivable-dashboard-which-payments-need-attention">Receivables</a><a href="#3-combined-dashboard-what-needs-a-decision">KPI worksheet</a><a href="#take-the-review-into-supaboard">Supaboard</a></nav>{article}</article><footer><p>Editorial review copy. Example figures are fictional. All Supaboard links use full URLs for republication.</p></footer></main></body></html>'''
(root/'financial-dashboard-examples.html').write_text(page)
(root/'article-fragment.html').write_text('<style>'+ (root/'figure-styles.css').read_text()+'</style>\n'+f'<article>\n<h1>{html.escape(fm["title"])}</h1>\n{article}\n</article>\n')
print(json.dumps({'body_words':words,'title_chars':len(fm['title']),'description_chars':len(fm['description']),'article_path':str(root/'financial-dashboard-examples.html')}))
